 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    # Find contiguous diagonal streaks; a nearby contrasting pixel marks the
    # origin, so continue the streak from its opposite end.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += dr; cc += dc
                if len(cells) < 2:
                    continue
                marked = []
                for i, (ar, ac) in enumerate(cells):
                    for nr in range(max(0, ar-1), min(h, ar+2)):
                        for nc in range(max(0, ac-1), min(w, ac+2)):
                            if grid[nr][nc] != bg and grid[nr][nc] != color:
                                marked.append(i)
                if not marked:
                    continue
                # Treat the endpoint closest to the contrasting marker as origin.
                origin_i = min(marked, key=lambda i: min(i, len(cells)-1-i))
                origin_end = 0 if origin_i <= (len(cells)-1)/2 else len(cells)-1
                if origin_end == 0:
                    er, ec = cells[-1]
                    sr, sc = dr, dc
                else:
                    er, ec = cells[0]
                    sr, sc = -dr, -dc
                rr, cc = er + sr, ec + sc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += sr; cc += sc
    return out
